"""Plot the model comparison metrics generated by the training runner."""

from __future__ import annotations

import argparse
from pathlib import Path

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from model.preprocess import PROJECT_ROOT

METRICS = ("Accuracy", "AUC", "Precision", "Recall", "F1", "MCC")
MODEL_COLUMN = "ML Model Name"


def plot_metrics(input_path: Path, output_path: Path) -> None:
    data = pd.read_csv(input_path)
    missing_columns = sorted({MODEL_COLUMN, *METRICS} - set(data.columns))
    if missing_columns:
        raise ValueError(f"Metrics CSV is missing required columns: {missing_columns}")
    if data.empty or data[MODEL_COLUMN].isna().any():
        raise ValueError("Metrics CSV must contain models with non-empty names.")

    for metric in METRICS:
        data[metric] = pd.to_numeric(data[metric], errors="raise")
        lower_bound = -1 if metric == "MCC" else 0
        if not np.isfinite(data[metric]).all() or not data[metric].between(lower_bound, 1).all():
            raise ValueError(f"{metric} contains invalid values.")

    fig, axes = plt.subplots(2, 3, figsize=(16, 9), constrained_layout=True)
    colors = plt.get_cmap("tab10")(np.arange(len(data)) % 10)
    for axis, metric in zip(axes.flat, METRICS):
        values = data[metric].to_numpy()
        positions = np.arange(len(data))
        axis.barh(positions, values, color=colors)
        axis.set_yticks(positions, labels=data[MODEL_COLUMN])
        axis.invert_yaxis()
        axis.set_title(metric)
        axis.set_xlabel("Score")
        axis.set_xlim(-1 if metric == "MCC" else 0, 1.15)
        axis.axvline(0, color="black", linewidth=0.6)
        for position, value in zip(positions, values):
            axis.annotate(
                f"{value:.3f}",
                (value, position),
                xytext=(3 if value >= 0 else -3, 0),
                textcoords="offset points",
                ha="left" if value >= 0 else "right",
                va="center",
                fontsize=8,
            )
    fig.suptitle("Held-out Test Metrics by Model", fontsize=16)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(output_path, dpi=180)
    plt.close(fig)
    print(f"Saved metric visualization: {output_path}")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--input", type=Path, default=PROJECT_ROOT / "model" / "results" / "model_metrics.csv"
    )
    parser.add_argument(
        "--output", type=Path, default=PROJECT_ROOT / "model" / "results" / "metrics_comparison.png"
    )
    args = parser.parse_args()
    plot_metrics(args.input, args.output)


if __name__ == "__main__":
    main()
